using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side shipment service with seed data.
/// Replace with EF Core / database access for production.
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = GenerateSeedData();

    public Task<List<Shipment>> GetShipmentsAsync(string? statusFilter = null)
    {
        var query = _shipments.AsEnumerable();
        if (!string.IsNullOrEmpty(statusFilter) &&
            Enum.TryParse<ShipmentStatus>(statusFilter, ignoreCase: true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }
        return Task.FromResult(query.OrderByDescending(s => s.ShippedDate).ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(
            s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        var results = _shipments
            .Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase))
            .OrderByDescending(s => s.ShippedDate)
            .ToList();
        return Task.FromResult(results);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = newStatus;
        return Task.CompletedTask;
    }

    private static List<Shipment> GenerateSeedData()
    {
        var now = DateTime.UtcNow;
        return
        [
            new()
            {
                Id = 1, TrackingNumber = "TRK-10001", Description = "Electronics — 2 pallets",
                Origin = "Shanghai, CN", Destination = "Los Angeles, US",
                Status = ShipmentStatus.InTransit, ShippedDate = now.AddDays(-5),
                EstimatedDelivery = now.AddDays(3), CustomerEmail = "alice@example.com"
            },
            new()
            {
                Id = 2, TrackingNumber = "TRK-10002", Description = "Auto parts — 1 container",
                Origin = "Stuttgart, DE", Destination = "Detroit, US",
                Status = ShipmentStatus.OutForDelivery, ShippedDate = now.AddDays(-8),
                EstimatedDelivery = now.AddDays(0), CustomerEmail = "bob@example.com"
            },
            new()
            {
                Id = 3, TrackingNumber = "TRK-10003", Description = "Textiles — 4 crates",
                Origin = "Mumbai, IN", Destination = "London, GB",
                Status = ShipmentStatus.Delivered, ShippedDate = now.AddDays(-12),
                EstimatedDelivery = now.AddDays(-2), CustomerEmail = "alice@example.com"
            },
            new()
            {
                Id = 4, TrackingNumber = "TRK-10004", Description = "Pharmaceuticals — temp-controlled",
                Origin = "Basel, CH", Destination = "São Paulo, BR",
                Status = ShipmentStatus.Delayed, ShippedDate = now.AddDays(-3),
                EstimatedDelivery = now.AddDays(5), CustomerEmail = "carol@example.com"
            },
            new()
            {
                Id = 5, TrackingNumber = "TRK-10005", Description = "Machinery — oversized",
                Origin = "Tokyo, JP", Destination = "Sydney, AU",
                Status = ShipmentStatus.PickedUp, ShippedDate = now.AddDays(-1),
                EstimatedDelivery = now.AddDays(7), CustomerEmail = "bob@example.com"
            },
            new()
            {
                Id = 6, TrackingNumber = "TRK-10006", Description = "Fresh produce — perishable",
                Origin = "Nairobi, KE", Destination = "Dubai, AE",
                Status = ShipmentStatus.Pending, ShippedDate = now,
                EstimatedDelivery = now.AddDays(2), CustomerEmail = "carol@example.com"
            }
        ];
    }
}

